void tick_screen_gps() {
    void *flowState = getFlowState(0, 5);
    (void)flowState;
    {
        const char *new_val = evalTextProperty(flowState, 23, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj214);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj214;
            lv_label_set_text(objects.obj214, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 25, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj216);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj216;
            lv_label_set_text(objects.obj216, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 26, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj217);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj217;
            lv_label_set_text(objects.obj217, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 27, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj218);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj218;
            lv_label_set_text(objects.obj218, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 30, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.gps_sat_table);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.gps_sat_table;
            lv_label_set_text(objects.gps_sat_table, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 32, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj222);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj222;
            lv_label_set_text(objects.obj222, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        bool new_val = evalBooleanProperty(flowState, 33, 3, "Failed to evaluate Hidden flag");
        bool cur_val = lv_obj_has_flag(objects.obj223, LV_OBJ_FLAG_HIDDEN);
        if (new_val != cur_val) {
            tick_value_change_obj = objects.obj223;
            if (new_val) {
                lv_obj_add_flag(objects.obj223, LV_OBJ_FLAG_HIDDEN);
            } else {
                lv_obj_clear_flag(objects.obj223, LV_OBJ_FLAG_HIDDEN);
            }
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 35, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.gps_raw_table);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.gps_raw_table;
            lv_label_set_text(objects.gps_raw_table, new_val);
            tick_value_change_obj = NULL;
        }
    }
}

