void tick_screen_route() {
    void *flowState = getFlowState(0, 6);
    (void)flowState;
    {
        const char *new_val = evalTextProperty(flowState, 23, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj247);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj247;
            lv_label_set_text(objects.obj247, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalStringArrayPropertyAndJoin(flowState, 27, 3, "Failed to evaluate Options in Dropdown widget", "\n");
        const char *cur_val = lv_dropdown_get_options(objects.obj250);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj250;
            lv_dropdown_set_options(objects.obj250, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        if (!(lv_obj_get_state(objects.obj250) & LV_STATE_EDITED)) {
            int32_t new_val = evalIntegerProperty(flowState, 27, 4, "Failed to evaluate Selected in Dropdown widget");
            int32_t cur_val = lv_dropdown_get_selected(objects.obj250);
            if (new_val != cur_val) {
                tick_value_change_obj = objects.obj250;
                lv_dropdown_set_selected(objects.obj250, new_val);
                tick_value_change_obj = NULL;
            }
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 34, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj257);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj257;
            lv_label_set_text(objects.obj257, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 35, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj258);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj258;
            lv_label_set_text(objects.obj258, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 36, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj259);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj259;
            lv_label_set_text(objects.obj259, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 42, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj265);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj265;
            lv_label_set_text(objects.obj265, new_val);
            tick_value_change_obj = NULL;
        }
    }
}

