void tick_screen_display() {
    void *flowState = getFlowState(0, 9);
    (void)flowState;
    {
        const char *new_val = evalTextProperty(flowState, 23, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj365);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj365;
            lv_label_set_text(objects.obj365, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 25, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj367);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj367;
            lv_label_set_text(objects.obj367, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        int32_t new_val = evalIntegerProperty(flowState, 26, 3, "Failed to evaluate Value in Slider widget");
        int32_t cur_val = lv_slider_get_value(objects.obj368);
        if (new_val != cur_val) {
            tick_value_change_obj = objects.obj368;
            lv_slider_set_value(objects.obj368, new_val, LV_ANIM_OFF);
            tick_value_change_obj = NULL;
        }
    }
    {
        if (!(lv_obj_get_state(objects.obj371) & LV_STATE_EDITED)) {
            int32_t new_val = evalIntegerProperty(flowState, 29, 3, "Failed to evaluate Selected in Dropdown widget");
            int32_t cur_val = lv_dropdown_get_selected(objects.obj371);
            if (new_val != cur_val) {
                tick_value_change_obj = objects.obj371;
                lv_dropdown_set_selected(objects.obj371, new_val);
                tick_value_change_obj = NULL;
            }
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 33, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj375);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj375;
            lv_label_set_text(objects.obj375, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 36, 3, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj378);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj378;
            lv_label_set_text(objects.obj378, new_val);
            tick_value_change_obj = NULL;
        }
    }
}

typedef void (*tick_screen_func_t)();
tick_screen_func_t tick_screen_funcs[] = {
    tick_screen_home,
    tick_screen_wifi,
    tick_screen_ble,
    tick_screen_can,
    tick_screen_io,
    tick_screen_gps,
    tick_screen_route,
    tick_screen_profile,
    tick_screen_ride,
    tick_screen_display,
};
void tick_screen(int screen_index) {
    if (screen_index >= 0 && screen_index < 10) {
        tick_screen_funcs[screen_index]();
    }
}
void tick_screen_by_id(enum ScreensEnum screenId) {
    tick_screen(screenId - 1);
}

